/** Phần cuối n dòng, như `tail -n n` (dòng cuối không có ký tự xuống dòng thừa). */
export function tailLines(text: string, n: number): string {
  const lines = text.replace(/\n$/, '').split('\n')
  return lines.slice(-n).join('\n')
}
